document.addEventListener('DOMContentLoaded',() =>{const STORAGE_KEY = 'tourDone';const tourEl = document.getElementById('user-tour');if (!tourEl || localStorage.getItem(STORAGE_KEY)) return;const dismissBtn = tourEl.querySelector('button,[data-tour-dismiss]');tourEl.classList.remove('hidden');tourEl.setAttribute('aria-hidden','false');const dismissTour = () =>{tourEl.classList.add('hidden');tourEl.setAttribute('aria-hidden','true');localStorage.setItem(STORAGE_KEY,'1');};if (dismissBtn){dismissBtn.addEventListener('click',dismissTour);}document.addEventListener('keydown',(e) =>{if (e.key === 'Escape' && !tourEl.classList.contains('hidden')){dismissTour();}});document.body.classList.add('overflow-hidden');tourEl.addEventListener('transitionend',() =>{if (tourEl.classList.contains('hidden')){document.body.classList.remove('overflow-hidden');}});});